package com.siam.vault;

import android.content.Intent;
import android.os.Bundle;
import android.view.Gravity;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.biometric.BiometricManager;
import androidx.biometric.BiometricPrompt;
import androidx.core.content.ContextCompat;
import com.siam.vault.database.AppDatabase;
import com.siam.vault.helper.PinHelper;
import com.siam.vault.helper.Ui;
import java.util.concurrent.Executor;

public class MainActivity extends AppCompatActivity {
    private TextView display;private final StringBuilder entry=new StringBuilder();private double left=0;private String operator="";private boolean fresh=true;
    @Override protected void onCreate(Bundle state){super.onCreate(state);if(!PinHelper.isConfigured(this)){startActivity(new Intent(this,SetPinActivity.class));finish();return;}drawCalculator();}
    private void drawCalculator(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,22),Ui.dp(this,36),Ui.dp(this,22),Ui.dp(this,18));root.setBackgroundColor(0xFFF8F9FA);TextView brand=Ui.text(this,"Calculator",20,true);brand.setOnLongClickListener(v->{resetPinDialog();return true;});root.addView(brand);display=Ui.text(this,"0",42,false);display.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);display.setSingleLine(true);display.setPadding(0,0,8,0);root.addView(display,new LinearLayout.LayoutParams(-1,0,1));GridLayout keys=new GridLayout(this);keys.setColumnCount(4);String[][] rows={{"AC","⌫","÷","×"},{"7","8","9","−"},{"4","5","6","+"},{"1","2","3","="},{"0","00",".","Biometric"}};for(String[] row:rows)for(String key:row){TextView b=Ui.text(this,key,key.equals("Biometric")?12:22,true);b.setGravity(Gravity.CENTER);b.setBackground(Ui.shape(key.equals("=")||key.equals("Biometric")?Ui.ORANGE:0xFFFFFFFF,Ui.dp(this,18),0xFFF1F1F1));if(key.equals("=")||key.equals("Biometric"))b.setTextColor(0xFFFFFFFF);b.setOnClickListener(v->press(key));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=Ui.dp(this,60);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(4,4,4,4);keys.addView(b,p);}root.addView(keys,new LinearLayout.LayoutParams(-1,-2));setContentView(root);}
    private void press(String key){if(key.equals("Biometric")){biometric();return;}if(key.equals("AC")){entry.setLength(0);operator="";left=0;fresh=true;display.setText("0");return;}if(key.equals("⌫")){if(entry.length()>0)entry.deleteCharAt(entry.length()-1);display.setText(entry.length()==0?"0":entry.toString());return;}if(key.equals("=")){equals();return;}if(key.equals("+")||key.equals("−")||key.equals("×")||key.equals("÷")){if(entry.length()>0){try{left=Double.parseDouble(entry.toString());}catch(Exception ignored){left=0;}operator=key;entry.setLength(0);fresh=true;}return;}if(key.equals(".")){if(entry.indexOf(".")<0)entry.append('.');}else{if(fresh){entry.setLength(0);fresh=false;}if(entry.length()<14)entry.append(key);}display.setText(entry.length()==0?"0":entry.toString());}
    private void equals(){String code=entry.toString();if(operator.isEmpty()&&code.matches("\\d{4}")){if(PinHelper.isLocked(this)){Toast.makeText(this,"৩ বার ভুল হয়েছে। ৩০ সেকেন্ড পরে চেষ্টা করুন।",Toast.LENGTH_LONG).show();return;}if(PinHelper.isFakePin(this,code)){PinHelper.clearFailures(this);open(true);return;}if(PinHelper.isRealPin(this,code)){PinHelper.clearFailures(this);open(false);return;}PinHelper.recordFailure(this);new AppDatabase(this).logAttempt();Toast.makeText(this,"ভুল PIN, আবার চেষ্টা করো",Toast.LENGTH_SHORT).show();entry.setLength(0);display.setText("0");fresh=true;return;}if(!operator.isEmpty()&&entry.length()>0){try{double right=Double.parseDouble(entry.toString()),result=left;if(operator.equals("+"))result+=right;else if(operator.equals("−"))result-=right;else if(operator.equals("×"))result*=right;else if(operator.equals("÷"))result=right==0?Double.NaN:result/right;String out=Double.isFinite(result)?(result==(long)result?String.valueOf((long)result):String.valueOf(result)):"Error";display.setText(out);entry.setLength(0);entry.append(out.equals("Error")?"":out);operator="";fresh=true;}catch(Exception e){display.setText("Error");entry.setLength(0);operator="";fresh=true;}}else if(entry.length()>0){try{double v=Double.parseDouble(entry.toString());display.setText(v==(long)v?String.valueOf((long)v):String.valueOf(v));entry.setLength(0);entry.append(display.getText());fresh=true;}catch(Exception ignored){}}}
    private void open(boolean decoy){entry.setLength(0);Intent i=new Intent(this,HomeActivity.class);i.putExtra("decoy",decoy);startActivity(i);finish();}
    private void biometric(){if(!PinHelper.hasBiometricEnabled(this)){Toast.makeText(this,"Profile থেকে Biometric unlock চালু করুন",Toast.LENGTH_SHORT).show();return;}int result=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG);if(result!=BiometricManager.BIOMETRIC_SUCCESS){Toast.makeText(this,"এই ডিভাইসে biometric প্রস্তুত নয়",Toast.LENGTH_SHORT).show();return;}Executor ex=ContextCompat.getMainExecutor(this);BiometricPrompt p=new BiometricPrompt(this,ex,new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){PinHelper.clearFailures(MainActivity.this);open(false);}});BiometricPrompt.PromptInfo info=new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock").setSubtitle("Fingerprint বা device credential").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).build();p.authenticate(info);}
    private void resetPinDialog(){EditText answer=new EditText(this);answer.setHint("তোমার প্রিয় খাবার কী?");new android.app.AlertDialog.Builder(this).setTitle("PIN recovery").setMessage("Calculator শিরোনামটি long-press করে এই recovery খোলা যায়।").setView(answer).setPositiveButton("পরবর্তী",(d,w)->{LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);EditText p=new EditText(this);p.setHint("নতুন PIN (৪ সংখ্যা)");p.setInputType(2|16);EditText c=new EditText(this);c.setHint("আবার PIN দিন");c.setInputType(2|16);fields.addView(p);fields.addView(c);new android.app.AlertDialog.Builder(this).setTitle("নতুন PIN").setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Save",(x,y)->{String freshPin=p.getText().toString();if(!freshPin.matches("\\d{4}")||!freshPin.equals(c.getText().toString())||PinHelper.isFakePin(this,freshPin)){Toast.makeText(this,"PIN যাচাই করুন; নকল PIN-এর সাথে আলাদা হতে হবে",Toast.LENGTH_LONG).show();return;}if(PinHelper.resetWithAnswer(this,answer.getText().toString(),freshPin))Toast.makeText(this,"PIN রিসেট হয়েছে",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"Recovery উত্তর মেলেনি",Toast.LENGTH_SHORT).show();}).show();}).setNegativeButton("Cancel",null).show();}
}
